@page "/settings"
@namespace sv_e0b5b170d2bf4277bbd5b07e95f47321.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    min-height: 600px;
    gap: 2rem;
    padding: 1rem;
}

::deep .settings-sidebar {
    display: flex;
    flex-direction: column;
    width: 200px;
    border-right: 1px solid #e0e0e0;
    padding-right: 1rem;
}

::deep .sidebar-item {
    padding: 0.75rem 1rem;
    border: none;
    background: none;
    text-align: left;
    cursor: pointer;
    border-radius: 6px;
    font-size: 0.95rem;
    color: #555;
    transition: background-color 0.2s, color 0.2s;
}

::deep .sidebar-item:hover {
    background-color: #f0f0f0;
}

::deep .sidebar-item.active {
    background-color: #e3f2fd;
    color: #1976d2;
    font-weight: 600;
}

.settings-content {
    flex: 1;
    max-width: 800px;
}

::deep .settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="password"],
::deep .form-group textarea,
::deep .form-group select {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

::deep .avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

::deep .avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
}

::deep .avatar-url {
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.5rem;
    word-break: break-all;
}

::deep .button-group {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

::deep .btn-primary {
    padding: 0.5rem 1.25rem;
    background-color: #1976d2;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-primary:hover {
    background-color: #1565c0;
}

::deep .btn-secondary {
    padding: 0.5rem 1.25rem;
    background-color: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-danger {
    padding: 0.5rem 1.25rem;
    background-color: #d32f2f;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-sm {
    padding: 0.25rem 0.6rem;
    font-size: 0.8rem;
}

::deep .toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

::deep .toast.success {
